    user "Create Merge Request" (doc="Create a merge request to the handbook") ->
    user "Merge Merge Request" ->
    user "Announce Change" (doc="Announce the change by linking to the diff") ->
    user "Close Issue" (doc="Close the issue with a link to the diff") ->
    xor "Is the change major or medium?" {
    [Major] -> send "Post Change in Main Slack Channel" (lane="Slack") -> end "End Major" (lane="Slack")
    [Medium] -> send "Post One-line Summary in Secondary Slack Channel" (lane="Slack") -> end "End Medium" (lane="Slack")
  }
  }
}

process "Handbook and Process Change Management" {
  @lane "Contributor" {
    start "Start" ->
