    [not specific to single function] -> xor "Is it cross-functional marketing?" {
    [cross-functional marketing] -> user "CMO approves cross-functional marketing MR" (lane="CMO Staff / CMO / Chief of Staff")
    [cross-company] -> user "Chief of Staff approves cross-company MR" (lane="CMO Staff / CMO / Chief of Staff")
  }
  }
  }
  @lane "Contributor" {
    -> user "Merge update on same day" #t05 ->
    xor "Is change a limited test?" {
    [is limited test] -> user "Add to handbook and note as limited test" -> xor "Is test over?" {
    [test is over] -> user "Remove note and apply to every case" -> user "Post merged change in Slack channel" #t06 -> xor "Communicating change for discussion and feedback?" {
    [for discussion and feedback] -> user "Link to unmerged diff"
    [not for discussion] -> user "Link to merged diff"
  } -> user "Communicate process change" #t07 -> user "Schedule retro issue" -> user "Document retro findings and evaluate new process" -> xor "Does someone make a good suggestion?" {
    [good suggestion made] -> user "Invite to add to handbook and offer help"
    [no good suggestion] -> ()
  } -> xor "Suggestion for large improvement on existing MR?" #g07 {
    [large improvement suggested] -> user "Create issue, merge existing MR, create new MR"
    [no large improvement] -> ()
  } -> xor "Do you need to move content?" #g08 {
    [need to move content] -> user "Create MR that only moves content, clean up after"
    [no need to move content] -> ()
  } -> end "End" #e03
    [test is not over] -> end "End Test Ongoing"
  }
    [not limited test] -> #t06
  }
  }
}

process "Handbook Usage and Communication Guidelines" {
